head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil10601";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil10601.onpageload' });
    }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name esgEditorUrl
 * @description esg Editor Url 처리
 * @returns {void}
 * @hidden N
 */
scwin.esgEditorUrl = function () {
    let url = "https://dev-editor.krx.co.kr/editor/login?hash=";
    if (location.hostname === 'idev-filing.krx.co.kr') {
        url = "https://idev-editor.krx.co.kr/editor/login?hash=";
    }
    url = "https://test-editor.krx.co.kr/editor/login?hash=";
    if (location.hostname === 'itest2-filing.krx.co.kr') {
        url = "https://itest2-editor.krx.co.kr/editor/login?hash=";
    }
    if (location.hostname === 'test2-filing.krx.co.kr') {
        url = "https://test2-editor.krx.co.kr/editor/login?hash=";
    }
    url = "https://editor.krx.co.kr/editor/login?hash=";
    url = "https://dr-editor.krx.co.kr/editor/login?hash=";
    return url;
};
